def action(gr,order,signs):
 target=g.GRCV4Graph(gr.live_node_ids[::-1],tuple(g.OrientedEdge(gr.oriented_edges[k].edge_id,gr.oriented_edges[k].tail_node_id if s==1 else gr.oriented_edges[k].head_node_id,gr.oriented_edges[k].head_node_id if s==1 else gr.oriented_edges[k].tail_node_id) for k,s in zip(order,signs)))
 return g.GraphCoordinateAction(gr,target,tuple(reversed(range(len(gr.live_node_ids)))),tuple(order),tuple(signs))
def expected_star(gr,vals):
 ends=[{e.tail_node_id,e.head_node_id} for e in gr.oriented_edges]
 with localcontext() as ctx:
  ctx.prec=2500
  out=[]
  for i,x in enumerate(vals):
   row=[]
   for j,y in enumerate(vals):
    c=len(ends[i]&ends[j])
    # Independent coefficient derivation, preserving specified sqrt/divide stages.
    sqrt_d=float(Decimal(len(ends[i])*len(ends[j])).sqrt())
    w=float(F(c)/F(sqrt_d))
    z=float(Decimal(w)*Decimal(x)*Decimal(y))
    if not math.isfinite(z):raise OverflowError('oracle final overflow')
    row.append(0.0 if z==0 else z)
   out.append(tuple(row))
 return tuple(out)
def star_case(kind,a,b):
