def positive(matrix):
 n=len(matrix);a=[[F(x) for x in r] for r in matrix]
 for k in range(n):
  if a[k][k]<=0:return False
  for i in range(k+1,n):
   for j in range(k+1,n):a[i][j]-=a[i][k]*a[k][j]/a[k][k]
 return True
for n in [2,3,5]:
 for scale in [-500,0,500]:
  for mode in ['pd','singular','indefinite']:
   base=[[float(1 if i==j else 0) for j in range(n)] for i in range(n)]
   base[0][0]=base[0][1]=base[1][0]=2.
   base[1][1]={'pd':math.nextafter(2.,math.inf),'singular':2.,'indefinite':math.nextafter(2.,0.)}[mode]
   mat=tuple(tuple(math.ldexp(x,scale) for x in row) for row in base)
   for p in [tuple(range(n)),tuple(reversed(range(n)))]:
    h=tuple(tuple(mat[i][j] for j in p) for i in p)
    def sp(h=h,n=n):
     exp=positive(h)
     try:obj=g.OneFormHodge(graph('parallel',n),h)
     except ValueError:assert not exp;return {'positive':False}
     assert exp;return {'positive':True}
