# Forward and backward solve independent Gauss-Jordan references.
def solve_q(a,b):
 n=len(b);w=[[F(x) for x in row]+[F(y)] for row,y in zip(a,b)]
 for k in range(n):
  p=next(i for i in range(k,n) if w[i][k]);w[k],w[p]=w[p],w[k];d=w[k][k];w[k]=[x/d for x in w[k]]
  for i in range(n):
   if i!=k:
    d=w[i][k];w[i]=[x-d*y for x,y in zip(w[i],w[k])]
 return [r[-1] for r in w]
for n in [2,3,6]:
 for e in [-700,0,700]:
  for k in range(4):
   l=[[rng.randint(-3,3) for _ in range(n)] for _ in range(n)]
   a=tuple(tuple(math.ldexp(float(sum(l[i][t]*l[j][t] for t in range(n))+(n if i==j else 0)),e) for j in range(n)) for i in range(n));b=tuple(math.ldexp(float(rng.randint(1,7)),e) for _ in range(n))
   def sol(a=a,b=b,n=n):
    gr=graph('parallel',n);x=g.PhysicalFluxFlatMap(g.OneFormHodge(gr,a)).flat(g.PhysicalFlux(gr,b)).values;exact=solve_q(a,b)
    f=max(abs(F(xi)-yi) for xi,yi in zip(x,exact))/max(abs(yi) for yi in exact)
    res=max(abs(sum(F(ai)*F(xi) for ai,xi in zip(row,x))-F(bi)) for row,bi in zip(a,b));scale=max(sum(abs(F(z)) for z in row) for row in a)*max(abs(F(z)) for z in x)+max(abs(F(z)) for z in b);r=res/scale
    assert f <=F(1,2**43),(float(f),float(r));assert r<=F(1,2**48)
    return {'relative_forward':float(f),'scaled_residual':float(r)}
   record('spd_independent_solve',f'{n}/{e}/{k}',sol)
